import React, { useState, useEffect } from "react";
import { collection, getDocs, deleteDoc, doc } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import "./ViewTeachersList.css";

const AdminViewTeachers = () => {
  const [teachers, setTeachers] = useState([]);
  const [editForm, setEditForm] = useState({ id: "", name: "", email: "", subject: "" });

  const TeachersCollectionRef = collection(db, "teachers");

  // Fetch teachers from Firestore and sort alphabetically by name
  const fetchTeachers = async () => {
    const data = await getDocs(TeachersCollectionRef);
    const teachersData = data.docs.map((doc) => ({ ...doc.data(), id: doc.id }));

    // Sort teachers alphabetically by name
    teachersData.sort((a, b) => a.name.localeCompare(b.name));

    setTeachers(teachersData);
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  // Handle Delete Action
  const handleDelete = async (id) => {
    try {
      await deleteDoc(doc(db, "teachers", id));
      alert("Teacher deleted successfully.");
      fetchTeachers(); // Refresh list
    } catch (error) {
      console.error("Error deleting teacher:", error);
    }
  };

  // Handle Edit Action
  const handleEdit = (teacher) => {
    setEditForm(teacher);
  };

  // Handle Update Action
  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      const teacherDoc = doc(db, "teachers", editForm.id);
      await updateDoc(teacherDoc, editForm);
      alert("Teacher updated successfully.");
      setEditForm({ id: "", name: "", email: "", subject: "" });
      fetchTeachers(); // Refresh list
    } catch (error) {
      console.error("Error updating teacher:", error);
    }
  };

  return (
    <div className="manage-students-container">
      <h2>View Registered Teachers</h2>

      {editForm.id && (
        <form onSubmit={handleUpdate} className="edit-form">
          <h3>Edit Teacher</h3>
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            value={editForm.name}
            onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}
            required
          />
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            name="email"
            value={editForm.email}
            onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}
            required
          />
          <label htmlFor="subject">Subject:</label>
          <input
            type="text"
            id="subject"
            name="subject"
            value={editForm.subject}
            onChange={(e) => setEditForm({ ...editForm, subject: e.target.value })}
            required
          />
          <button type="submit" className="form-btn">Update Teacher</button>
        </form>
      )}

      <table className="students-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Email</th>
            <th>Subject</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {teachers.length === 0 ? (
            <tr>
              <td colSpan="4">No teachers registered yet.</td>
            </tr>
          ) : (
            teachers.map((teacher) => (
              <tr key={teacher.id}>
                <td>{teacher.name}</td>
                <td>{teacher.email}</td>
                <td>{teacher.subject}</td>
                <td>
                  <button className="edit-btn" onClick={() => handleEdit(teacher)}>Edit</button>
                  <button className="delete-btn" onClick={() => handleDelete(teacher.id)}>Delete</button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default AdminViewTeachers;
